// Synthetic renderer only: no Argus bootstrap, live profile, backend or model.
const { app, BrowserWindow, session } = require("electron");
const assert = require("node:assert/strict");
const fs = require("node:fs/promises");
const path = require("node:path");
const temporary = process.argv[2];
if (!temporary || !path.isAbsolute(temporary) || !path.basename(temporary).startsWith("argus-revision-scope-368-")) throw new Error("Isolated test directory required");
for (const key of ["userData", "sessionData", "logs"]) app.setPath(key, path.join(temporary, key));
app.commandLine.appendSwitch("disable-background-networking");
const root = path.resolve(__dirname, "../..");
let window, network = 0;
const timer = setTimeout(() => { console.error("Scope fixture timed out"); app.exit(1); }, 50_000);
const finish = code => { clearTimeout(timer); window?.destroy(); app.exit(code); };
app.whenReady().then(async () => {
  const index = await fs.readFile(path.join(root, "public/index.html"), "utf8");
  const files = [...index.matchAll(/<link\s+rel="stylesheet"\s+href="\/([^"?]+)[^"]*"[^>]*>/g)].map(match => match[1]);
  const styles = (await Promise.all(files.map(file => fs.readFile(path.join(root, "public", file), "utf8")))).join("\n");
  const module = (await fs.readFile(path.join(root, "public/revision-scope-picker.mjs"), "utf8")).replace(/^export /gm, "");
  const isolated = session.fromPartition("revision-scope-368", { cache: false });
  isolated.setPermissionRequestHandler((_contents, _permission, callback) => callback(false));
  isolated.webRequest.onBeforeRequest((details, callback) => { const blocked = !details.url.startsWith("data:"); if (blocked) network++; callback({ cancel: blocked }); });
  window = new BrowserWindow({ show: false, width: 1280, height: 800, webPreferences: { session: isolated, contextIsolation: true, nodeIntegration: false, sandbox: true, backgroundThrottling: false } });
  const html = `<html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:"><style>${styles}</style></head><body data-view="global"><button id="opener">Edit saved prompt</button><textarea id="unsent">Keep this unrelated unsent draft</textarea></body></html>`;
  await window.loadURL(`data:text/html;charset=utf-8,${encodeURIComponent(html)}`);
  const run = script => window.webContents.executeJavaScript(script);
  const settle = () => run("new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))");
  await run(`${module}\nwindow.choose = createRevisionScopePicker({document});
    window.repositories = Array.from({length:14}, (_,i) => ({id:'repo-'+i,name:i===2?'very-long-repository-name-with-extra-unbroken-characters-ABCDEFGHIJKLMNOPQRSTUVWXYZ': 'Connected service '+i}));
    window.input = {task:{repositoryIds:['repo-0','repo-1','old-chat-service']},repositories,disconnectedRepositories:[{id:'old-chat-service',name:'chat-service (disconnected)'}]};
    window.openScope = (input = window.input) => { document.querySelector('#opener').focus(); window.choiceResult = 'waiting'; window.choicePromise = choose(input).then(result => {window.choiceResult=result;}); };
    window.measure = () => { const d=document.querySelector('#revision-scope-dialog'),r=d.getBoundingClientRect(); return {bounds:{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height},vw:innerWidth,vh:innerHeight,scrollWidth:d.scrollWidth,clientWidth:d.clientWidth,focused:document.activeElement?.getAttribute('data-scope-cancel') !== null,auto:d.querySelector('[data-scope-auto]').checked,selected:[...d.querySelectorAll('input[name=repository]:checked')].map(x=>x.value),text:d.textContent}; }; undefined;`);
  const layouts = [];
  for (const theme of ["dark", "light"]) for (const width of [320, 640, 1280]) for (const font of ["system", "comic-sans"]) for (const zoom of [1, 1.22]) {
    window.setSize(width, width === 320 ? 600 : 800);
    await run(`document.documentElement.dataset.theme=${JSON.stringify(theme)}; document.documentElement.dataset.fontFamily=${JSON.stringify(font)}; document.documentElement.style.zoom=${zoom}; openScope(); undefined;`);
    await settle();
    const measurement = await run("measure()");
    const initialHeading = await run("(()=>{const d=document.querySelector('#revision-scope-dialog'),r=d.querySelector('h2').getBoundingClientRect();return {top:r.top,bottom:r.bottom,scrollTop:d.scrollTop}})()");
    const details = JSON.stringify({ theme, width, font, zoom, ...measurement });
    assert.ok(measurement.bounds.left >= -1 && measurement.bounds.top >= -1 && measurement.bounds.right <= measurement.vw + 1 && measurement.bounds.bottom <= measurement.vh + 1, details);
    assert.ok(measurement.scrollWidth <= measurement.clientWidth + 2, details);
    assert.equal(measurement.auto, false, details);
    assert.equal(measurement.focused, true, details);
    assert.deepEqual(measurement.selected, ["repo-0", "repo-1"], details);
    assert.match(measurement.text, /chat-service \(disconnected\)/);
    assert.ok(initialHeading.top >= measurement.bounds.top && initialHeading.bottom <= measurement.bounds.bottom, JSON.stringify({ details, initialHeading }));
    if (process.env.ARGUS_REVISION_SCOPE_CAPTURE === "1" && zoom === 1 && font === "system") await fs.writeFile(path.join(temporary, `${theme}-${width}-initial.png`), (await window.webContents.capturePage()).toPNG());
    await run("document.querySelector('#revision-scope-dialog').scrollTop=100000; undefined;"); await settle();
    const actions = await run("[...document.querySelectorAll('#revision-scope-dialog footer button')].map(x=>{const r=x.getBoundingClientRect();return {left:r.left,right:r.right,top:r.top,bottom:r.bottom}})");
    for (const r of actions) assert.ok(r.left >= measurement.bounds.left && r.right <= measurement.bounds.right + 1 && r.top >= measurement.bounds.top && r.bottom <= measurement.bounds.bottom + 1, JSON.stringify({ details, r }));
    if (process.env.ARGUS_REVISION_SCOPE_CAPTURE === "1" && zoom === 1 && font === "system") await fs.writeFile(path.join(temporary, `${theme}-${width}.png`), (await window.webContents.capturePage()).toPNG());
    await run("document.querySelector('[data-scope-cancel]').click(); window.choicePromise");
    assert.equal(await run("window.choiceResult"), null);
    assert.equal(await run("document.querySelector('#unsent').value"), "Keep this unrelated unsent draft");
    layouts.push({ theme, width, font, zoom, bounds: measurement.bounds });
  }
  await run("openScope(); document.querySelector('#revision-scope-dialog form').requestSubmit(); window.choicePromise");
  assert.deepEqual(await run("window.choiceResult"), { repositoryIds: ["repo-0", "repo-1"], expectedRepositoryIds: ["repo-0", "repo-1", "old-chat-service"] });
  await run("openScope(); document.querySelector('[data-scope-auto]').click(); document.querySelector('#revision-scope-dialog form').requestSubmit(); window.choicePromise");
  assert.deepEqual(await run("window.choiceResult.repositoryIds"), []);
  await run("openScope(); for (const x of document.querySelectorAll('input[name=repository]')) x.checked=true; document.querySelector('#revision-scope-dialog form').requestSubmit(); undefined;");
  assert.match(await run("document.querySelector('[data-scope-error]').textContent"), /up to 6/);
  await run("document.querySelector('#revision-scope-dialog').dispatchEvent(new Event('cancel',{cancelable:true})); window.choicePromise");
  assert.equal(await run("window.choiceResult"), null);
  await run("openScope({...input,repositories:[]}); undefined;");
  assert.equal(await run("document.querySelector('#revision-scope-dialog button[type=submit]').disabled"), true);
  await run("document.querySelector('[data-scope-cancel]').click(); window.choicePromise");
  await fs.writeFile(path.join(temporary, "results.json"), JSON.stringify({ layouts, selectionChecks: "PASS", network }, null, 2));
  finish(0);
}).catch(error => { console.error(error.stack || error); finish(1); });
